<script lang="ts">
  import {cancel,health,history,imageUrl,krea2Workflow,provision,runPodSettings,runtimeHealth,setRunPodSettings,submit,terminate,type ComfyHistory,type Pod} from './api';
  import {displayUrl,loadImages,saveRemoteImage} from './library';
  const DEFAULT_PROMPT='cinematic portrait of a woman outside a convenience store at night, rain reflections, soft tungsten light, natural skin texture';
  let tab:'create'|'library'|'settings'='create',prompt=DEFAULT_PROMPT,seed=42,width=1024,height=1024;
  let configured=false,busy=false,message='Checking gateway…',images:string[]=[],library:string[]=[];
  let worker:Pod|null=null,promptId:string|null=null,idleTimer:ReturnType<typeof setTimeout>|null=null;
  let provider=runPodSettings(),apiKey=provider.apiKey,showKey=false;
  const sleep=(ms:number)=>new Promise(resolve=>setTimeout(resolve,ms));
  health().then(result=>{configured=result.configured;message=result.configured?'Worker sleeping':'Add your RunPod API key in Settings'}).catch(error=>message=error.message);
  loadImages().then(saved=>library=saved.map(displayUrl)).catch(()=>{});
  function validDimension(value:number){return Math.max(256,Math.min(2048,Math.round(value/16)*16))}
  async function ensureWorker(){
    if(worker){try{await runtimeHealth(worker.id);return worker}catch{/* stale or booting */}}
    message='Finding a 24 GB GPU…';worker=await provision();message=`Pod ${worker.id} provisioning`;
    for(let attempt=0;attempt<120;attempt++){if(!worker)throw new Error('Worker was stopped');try{await runtimeHealth(worker.id);message='Krea 2 worker ready';return worker}catch{await sleep(5000);message=`Worker booting · ${(attempt+1)*5}s`}}
    throw new Error('Worker did not become ready within 10 minutes');
  }
  function scheduleIdleStop(){if(idleTimer)clearTimeout(idleTimer);idleTimer=setTimeout(()=>stopWorker('Stopped after 20 idle minutes'),20*60_000)}
  async function generate(){try{
    busy=true;images=[];width=validDimension(width);height=validDimension(height);const ready=await ensureWorker();message='Submitting Krea 2 workflow…';
    const job=await submit(ready.id,krea2Workflow(prompt,seed,width,height));promptId=job.prompt_id;if(!promptId)throw new Error('ComfyUI did not return a prompt ID');
    for(;;){await sleep(1500);const result=await history(ready.id,promptId);const record:ComfyHistory|undefined=result[promptId];const outputImages=Object.values(record?.outputs||{}).flatMap(output=>output.images||[]);if(outputImages.length){images=outputImages.map(image=>imageUrl(ready.id,image));message='Persisting images…';const saved=await Promise.all(images.map(url=>saveRemoteImage(url,prompt)));library=[...saved.map(displayUrl),...library];message=`Generated and saved ${images.length} image${images.length===1?'':'s'}`;break}if(record?.status?.status_str==='error')throw new Error('ComfyUI generation failed');message='Generating with Krea 2 Turbo…'}
    scheduleIdleStop();
  }catch(error){message=error instanceof Error?error.message:String(error)}finally{busy=false;promptId=null}}
  async function cancelJob(){if(worker&&promptId){await cancel(worker.id,promptId);busy=false;promptId=null;message='Generation cancelled';scheduleIdleStop()}}
  async function stopWorker(done='Worker terminated'){if(!worker)return;const id=worker.id;worker=null;if(idleTimer)clearTimeout(idleTimer);try{await terminate(id);message=done}catch(error){message=error instanceof Error?error.message:String(error)}}
  async function saveProvider(){setRunPodSettings(apiKey);try{const result=await health();configured=result.configured;message=result.configured?'RunPod settings ready':'API key is required'}catch(error){configured=false;message=error instanceof Error?error.message:String(error)}}
</script>
<svelte:head><title>Flujo v0.1</title></svelte:head>
<header><b><i></i>flujo</b><nav><button class:active={tab==='create'} onclick={()=>tab='create'}>Create</button><button class:active={tab==='library'} onclick={()=>tab='library'}>Library</button><button class:active={tab==='settings'} onclick={()=>tab='settings'}>Settings</button></nav><span class="status"><em class:ok={configured&&!busy} class:working={busy}></em>{message}</span></header>
{#if tab==='create'}<main><section class="results">{#each images as image}<img src={image} alt="Generated result">{/each}{#if busy}<div class="loading"><span></span>{message}</div>{/if}</section><section class="composer"><textarea bind:value={prompt} placeholder="Describe an image"></textarea><div><label>Seed <input type="number" bind:value={seed}></label><label>W <input type="number" bind:value={width}></label><label>H <input type="number" bind:value={height}></label>{#if busy}<button class="danger" onclick={cancelJob}>Cancel</button>{/if}<button class="go" disabled={busy||!configured} onclick={generate}>Generate</button></div></section></main>
{:else if tab==='library'}<main><h1>Library</h1>{#if library.length===0}<p class="muted">Generated images from this session appear here.</p>{/if}<section class="results">{#each library as image}<img src={image} alt="Generated result">{/each}</section></main>
{:else}<main><h1>Settings</h1><section class="card"><h2>RunPod</h2><p>Enter an API key for this browser session. Flujo owns the released Krea 2 Pod template; users do not configure images, templates, or runtime endpoints.</p><label class="field"><span>API key</span><div><input type={showKey?'text':'password'} bind:value={apiKey} autocomplete="off" placeholder="rpa_…"><button onclick={()=>showKey=!showKey}>{showKey?'Hide':'Show'}</button></div></label><button class="go save" onclick={saveProvider}>Save session key</button></section><section class="card"><h2>Compute</h2><p>Krea 2 Turbo FP8 · normal RunPod Pod · 24 GB minimum VRAM · automatic start on Generate.</p><div class="worker"><span>{worker?`Pod ${worker.id}`:'Sleeping'}</span>{#if worker}<button class="danger" onclick={()=>stopWorker()}>Terminate now</button>{/if}</div><p>Ready workers terminate after 20 idle minutes. The application-owned template is pinned to the released worker image.</p></section><section class="card"><h2>Workflow</h2><p>The tested 8-step Krea 2 Turbo workflow is bundled with Flujo. No ComfyUI workflow paste is required.</p></section></main>{/if}
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:radial-gradient(circle at 85% 0,#171a2a 0,transparent 28%),#0d0f12;color:#f5f7fa;font:14px/1.5 Inter,system-ui}:global(button),:global(input),:global(textarea){font:inherit;color:inherit}header{height:60px;border-bottom:1px solid #2a2f38;display:flex;align-items:center;padding:0 22px;gap:28px;position:sticky;top:0;background:#0d0f12e8;backdrop-filter:blur(14px);z-index:5}header b{font-size:20px}header i{display:inline-block;width:25px;height:25px;border-radius:8px;background:linear-gradient(135deg,#7d8cff,#a07cff);vertical-align:-7px;margin-right:8px}nav{display:flex;gap:5px}button{border:0;border-radius:9px;background:transparent;padding:9px 12px;cursor:pointer;color:#9299a5}button.active,button:hover{background:#1b1f25;color:white}.status{margin-left:auto;color:#9299a5}.status em{width:8px;height:8px;border-radius:50%;display:inline-block;background:#6e7580;margin-right:8px}.status em.ok{background:#55d69d}.status em.working{background:#f0c566;animation:pulse 1s infinite}@keyframes pulse{50%{opacity:.3}}main{max-width:1120px;margin:auto;padding:32px 20px 180px}.results{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.results img,.loading{width:100%;aspect-ratio:1/1;border-radius:16px;background:#1b1f25;object-fit:cover}.loading{display:grid;place-items:center;color:#9299a5;text-align:center;padding:20px}.loading span{width:30px;height:30px;border:3px solid #39404b;border-top-color:#7d8cff;border-radius:50%;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.composer{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);width:min(820px,calc(100vw - 28px));background:#171a1fee;border:1px solid #39404b;border-radius:18px;padding:12px;box-shadow:0 24px 70px #0009}.composer textarea{width:100%;height:70px;resize:none;background:none;border:0;outline:0}.composer>div{display:flex;gap:10px;align-items:center;border-top:1px solid #2a2f38;padding-top:10px}.composer label{color:#9299a5}.composer input{width:90px;background:#1b1f25;border:1px solid #2a2f38;border-radius:7px;padding:7px}.go{background:#7d8cff;color:white;margin-left:auto}.go:disabled{opacity:.4}.danger{color:#ff9ca8}.card{background:#15181d;border:1px solid #2a2f38;border-radius:16px;padding:18px;margin-bottom:14px}.card p,.muted{color:#9299a5}.worker{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #2a2f38;border-bottom:1px solid #2a2f38;padding:12px 0}.field{display:grid;grid-template-columns:150px 1fr;gap:12px;align-items:center;padding:10px 0}.field>div{width:100%}.field input{width:100%;background:#101216;border:1px solid #39404b;border-radius:9px;padding:10px}.field div{display:flex;gap:7px}.field div button{border:1px solid #39404b}.save{margin:12px 0 0 150px}@media(max-width:700px){nav{display:none}.status{max-width:190px;white-space:nowrap;overflow:hidden}.results{grid-template-columns:repeat(2,1fr)}.composer label:nth-child(n+2){display:none}.field{grid-template-columns:1fr}.save{margin-left:0}}
</style>
